export function Form({
  title = "{{title}}",
  submitLabel = "{{submitLabel}}",
  accent = "{{accent}}",
  layout = "{{layout}}",
  radius = {{radius}},
}) {
  const inputStyle = {
    width: "100%", boxSizing: "border-box", padding: "10px 12px", font: "inherit", color: "#241430",
    background: "#FAF7F2", border: "1.5px solid #24143040", borderRadius: radius,
  };
  return (
    <form noValidate style={{
      fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: layout === "inline" ? 480 : 320,
      display: "flex", flexDirection: layout === "inline" ? "row" : "column", flexWrap: "wrap", alignItems: layout === "inline" ? "flex-end" : "stretch", gap: 12,
    }}>
      <h2 style={{ margin: "0 0 4px", fontSize: 16, width: layout === "inline" ? "100%" : "auto" }}>{title}</h2>
      <label style={{ display: "block", flex: 1, minWidth: 140 }}>
        <span style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>Name</span>
        <input type="text" name="name" autoComplete="name" required style={inputStyle} />
      </label>
      <label style={{ display: "block", flex: 1, minWidth: 140 }}>
        <span style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>Email</span>
        <input type="email" name="email" autoComplete="email" required style={inputStyle} />
      </label>
      <button type="submit" style={{ padding: "10px 18px", border: "none", background: accent, color: "#FAF7F2", font: "inherit", fontWeight: 600, cursor: "pointer", borderRadius: radius }}>
        {submitLabel}
      </button>
    </form>
  );
}
